import{_ as n,o as t,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const a="/assets/132_e45aa53e-5d1b-4b3c-abe1-e3449743d80f.tJR6ma_q.png",s="/assets/137_6f403f49ebe86018dd6ddf6a76d2dcd8.BaxkQNn9.png",f=JSON.parse('{"title":"Domain registration information requirements","description":"","frontmatter":{"title":"Domain registration information requirements"},"headers":[],"relativePath":"operations-knowledge-base/sales-issues/domain-registration-information-requirements.md","filePath":"operations-knowledge-base/sales-issues/domain-registration-information-requirements.md","lastUpdated":1794292919000}'),r={name:"operations-knowledge-base/sales-issues/domain-registration-information-requirements.md"};function l(d,e,m,p,u,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<p>1.Before registering a domain, please modify your account information to meet the requirements of domain name registration information as follows:</p><p>（1）Click on the avatar in the top right corner.</p><p>（2）Click on &quot;Account Details&quot;.</p><p>（3）Name must not be empty, and can only use English or Pinyin.</p><p>（4）Surname must not be empty, and can only use English or Pinyin.</p><p>（5）Company name can be left blank. If filled in, it can only use English or Pinyin.</p><p>（6）Email address must be a valid and legal address. You need to receive a verification email to activate the domain name.</p><p>（7）The first line of the street address must not be empty, and can only use English, Pinyin, and numbers.</p><p>（8）The second line of the street address can be left blank. If filled in, it can only use English, Pinyin, and numbers.</p><p>（9）City must be filled in, and can only use English or Pinyin. It must correspond to Country&gt;&gt;Province&gt;&gt;City.</p><p>（10）Province must be filled in, and can only use English or Pinyin. It must correspond to Country&gt;&gt;Province.</p><p>（11）Country must be filled in.</p><p>（12）Postal code must be filled in, and can only use English or Pinyin. It must correspond to Country&gt;&gt;Province&gt;&gt;City&gt;&gt;Postal Code.</p><p>（13）Mobile phone number must be filled in, and make sure it matches the relevant code rules of the selected region.</p><p><img src="'+a+'" alt=""></p><p>2.When registering a domain, as shown in the figure below, you need to create or select contact information:</p><p>(1）Click on &quot;Help Center&quot; to view domain name information related requirements</p><p>(2）Create or select contact information. If you have not created contact information before, you must create a new one for the first time you register a domain name. If you have created one before, you can directly click to select.</p><p>(3）Name must not be empty, and can only use English or Pinyin</p><p>(4）Surname must not be empty, and can only use English or Pinyin</p><p>(5）Company name can be left blank. If filled in, it can only use English or Pinyin</p><p>(6）Email address must be a valid and legal address. You need to receive a verification email to activate the domain name</p><p>(7）The first line of the street address must not be empty, and can only use English, Pinyin, and numbers</p><p>(8）The second line of the street address can be left blank. If filled in, it can only use English, Pinyin, and numbers</p><p>(9）City must be filled in, and can only use English or Pinyin. It must correspond to Country&gt;&gt;Province&gt;&gt;City.</p><p>(10）Province must be filled in, and can only use English or Pinyin. It must correspond to Country&gt;&gt;Province.</p><p>(11）Country must be filled in.</p><p>(12）Postal code must be filled in, and can only use English or Pinyin. It must correspond to Country&gt;&gt;Province&gt;&gt;City&gt;&gt;Postal Code.</p><p>(13）Mobile phone number must be filled in, and make sure it matches the relevant code rules of the selected region.</p><p><img src="'+s+'" alt=""></p><p>3.Important reminder: The domain registration information must meet the above requirements, and Country&gt;&gt;Province&gt;&gt;City&gt;&gt;Postal Code must correspond, otherwise the registration will not be successful!</p>',31)])])}const y=n(r,[["render",l]]);export{f as __pageData,y as default};
